wt.plot<-ggplot(wgtsnna %>% filter(year %in% c(1991:2020, 2071:2100)),aes(x = as.factor(age), y = wgtmd, color=Period)) +
  geom_boxplot(outliers=FALSE)+
  labs(title = "", x = "Age", y = "Weight (g)") +
